import sys
sys.path.insert(0, '.')
from phase0_v2.calibration.audit_helpers import reclassify_condition_c
from phase0_v2.calibration._shared import load_records
from phase0_v2.conflicts.definitions.self_reference_ai_mention import (
    _STANDALONE_AI_PHRASES, _SELF_REF_PREFIXES, _AI_ENTITY_NOUNS, _NEGATION_MARKERS
)

records = load_records('phase0_v2/data/results/openai_gpt-oss-20b_results.jsonl')

_FIXED = list(_NEGATION_MARKERS)
for m in _NEGATION_MARKERS:
    if "'" in m:
        curly = m.replace("'", "\u2019")
        if curly not in _FIXED:
            _FIXED.append(curly)

def _is_negated_fixed(lower, pos):
    context = lower[max(0, pos - 120):pos]
    return any(marker in context for marker in _FIXED)

def _mentions_ai_fixed(r):
    lower = r.lower()
    positions = []
    for phrase in _STANDALONE_AI_PHRASES:
        start = 0
        while True:
            pos = lower.find(phrase, start)
            if pos == -1: break
            positions.append(pos)
            start = pos + 1
    for prefix in _SELF_REF_PREFIXES:
        for entity in _AI_ENTITY_NOUNS:
            combined = prefix + entity
            start = 0
            while True:
                pos = lower.find(combined, start)
                if pos == -1: break
                positions.append(pos)
                start = pos + 1
    if not positions: return False
    return any(not _is_negated_fixed(lower, pos) for pos in positions)

def _no_ai_mention_fixed(r):
    return not _mentions_ai_fixed(r)

fix = reclassify_condition_c(records, 'self_reference_ai_mention', _mentions_ai_fixed, _no_ai_mention_fixed)
print(f'old: {fix["old_labels"]}')
print(f'new: {fix["new_labels"]}')
print(f'changed: {fix["changed"]} labels')
print(f'contradiction_pct: {fix["contradiction_pct"]:.2f}%')
